# frozen_string_literal: true

require 'base64'
require 'openssl'

module AccountsPayable
  # Verifies the CFDI issuer's RSA-SHA256 seal against the embedded X.509 certificate.
  # The canonical string MUST be generated by the complete, trusted SAT CFDI 4.0
  # stylesheet (including its official dependencies). Missing resources fail closed.
  class CfdiSignatureVerifier
    STYLESHEET = Rails.root.join('config/sat/cadenaoriginal_4_0.xslt')

    def self.call(xml:)
      raise ArgumentError, 'CFDI stylesheet is not installed' unless STYLESHEET.file?
      raise ArgumentError, 'CFDI document exceeds 10 MB' if xml.bytesize > 10.megabytes

      document = Nokogiri::XML(xml) { |options| options.strict.nonet }
      root = document.root
      raise ArgumentError, 'Invalid CFDI 4.0' unless root&.name == 'Comprobante' &&
                                                     root.namespace&.href == AccountsPayable::CfdiParser::CFDI_NS &&
                                                     root['Version'] == '4.0'

      certificate = OpenSSL::X509::Certificate.new(Base64.strict_decode64(root['Certificado']))
      seal = Base64.strict_decode64(root['Sello'])
      raise ArgumentError, 'CFDI certificate is not valid at issue date' unless certificate_valid?(certificate, root)
      raise ArgumentError, 'Certificate number does not match CFDI' unless certificate_number(certificate) == root['NoCertificado']

      stylesheet = Nokogiri::XSLT(File.read(STYLESHEET))
      chain = stylesheet.transform(document).to_s
      valid = certificate.public_key.verify(OpenSSL::Digest::SHA256.new, seal, chain)
      raise ArgumentError, 'Invalid CFDI digital signature' unless valid

      true
    rescue OpenSSL::OpenSSLError, ArgumentError, Nokogiri::XML::SyntaxError, Nokogiri::XSLT::SyntaxError,
           KeyError => e
      raise ArgumentError, "CFDI signature verification failed: #{e.message}"
    end

    def self.certificate_valid?(certificate, root)
      issued_at = Time.iso8601(root['Fecha'])
      certificate.not_before <= issued_at && issued_at <= certificate.not_after
    end

    def self.certificate_number(certificate)
      certificate.serial.to_s(16).scan(/../).map { |byte| byte.to_i(16).chr }.join
    end
  end
end
